+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ * <p>
+ * The store can be configured through the following properties:
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=...          # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_DEFAULT = "ignore";
+    private static final String RANDOM_FILE_NAMES = "random";
+    private static final String DESCRIPTION_FILE_NAMES = "description";
+
+    private static final ConcurrentHashMap<String, StoreState> STORES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean hasConstructorStrategy;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private IntegrityMode integrityMode;
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private StoreState storeState;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+        hasConstructorStrategy = false;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        constructorStrategy = Preconditions.checkNotNull(ruleViolationFileNameStrategy);
+        hasConstructorStrategy = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        Properties configuration = properties == null ? new Properties() : properties;
+        storeCreationAllowed = Boolean.parseBoolean(configuration.getProperty(
+                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(configuration.getProperty(
+                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(configuration.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        ruleViolationFileNameStrategy = resolveFileNameStrategy(configuration);
+
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires updating the violation store (enable by configuration %s=true)",
+                    ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        File folder = new File(configuration.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        File index = new File(folder, STORED_RULES_FILE_NAME);
+        String storeKey = canonicalPath(index);
+        StoreState state = STORES_BY_PATH.computeIfAbsent(storeKey, ignored -> new StoreState(folder, index));
+
+        synchronized (state.lock) {
+            prepareStorage(state, integrityMode);
+            Properties loaded = loadProperties(state.index);
+            IntegrityInspection inspection = null;
+            if (integrityMode != IntegrityMode.IGNORE) {
+                inspection = inspect(loaded, state);
+                if (integrityMode == IntegrityMode.FAIL) {
+                    rejectIfInconsistent(inspection);
+                } else {
+                    repair(loaded, state, inspection);
+                }
+            }
+            state.properties = loaded;
+            state.initialized = true;
+            storeState = state;
+        }
+        log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), state.index.getAbsolutePath());
+    }
+
+    private RuleViolationFileNameStrategy resolveFileNameStrategy(Properties properties) {
+        if (hasConstructorStrategy) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(
+                        "Cannot configure " + FILE_NAMES_PROPERTY_NAME + " for a store using a constructor strategy");
+            }
+            return constructorStrategy;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, RANDOM_FILE_NAMES);
+        if (RANDOM_FILE_NAMES.equals(configured)) {
+            return ignored -> UUID.randomUUID().toString();
+        }
+        if (DESCRIPTION_FILE_NAMES.equals(configured)) {
+            return TextFileBasedViolationStore::descriptionFileName;
+        }
+        try {
+            Class<?> strategyClass = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
+            }
+            return (RuleViolationFileNameStrategy) strategyClass.getConstructor().newInstance();
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid %s '%s'; expected 'random', 'description', or a RuleViolationFileNameStrategy with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private static String descriptionFileName(String description) {
+        String selectedWord = null;
+        StringBuilder currentWord = new StringBuilder();
+        for (int i = 0; i < description.length(); i++) {
+            char character = description.charAt(i);
+            if (isAsciiLetterOrDigit(character)) {
+                currentWord.append(character);
+            } else {
+                if (currentWord.length() >= 4 && currentWord.length() <= 120) {
+                    selectedWord = currentWord.toString();
+                }
+                currentWord.setLength(0);
+            }
+        }
+        if (currentWord.length() >= 4 && currentWord.length() <= 120) {
+            selectedWord = currentWord.toString();
+        }
+
+        String wordPart = selectedWord == null ? "rule" : selectedWord;
+        return "rule-" + wordPart + "-" + sha256(description);
+    }
+
+    private static boolean isAsciiLetterOrDigit(char character) {
+        return character >= 'a' && character <= 'z'
+                || character >= 'A' && character <= 'Z'
+                || character >= '0' && character <= '9';
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte part : digest) {
+                result.append(String.format("%02x", part & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private void prepareStorage(StoreState state, IntegrityMode requestedIntegrity) {
+        File folder = state.folder;
+        File index = state.index;
+        boolean indexExists = Files.exists(index.toPath(), LinkOption.NOFOLLOW_LINKS);
+
+        if (!indexExists && requestedIntegrity == IntegrityMode.FAIL) {
+            throw new StoreInitializationFailedException(
+                    "Integrity fail requires an existing regular stored.rules file; no index was created");
+        }
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s=true)",
+                    ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        try {
+            if (!Files.exists(folder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                if (!folder.mkdirs() && !folder.isDirectory()) {
+                    throw new IOException("Could not create store folder");
+                }
+            }
+            if (!folder.isDirectory()) {
+                throw new IOException("Store path is not a directory");
+            }
+
+            if (!indexExists) {
+                Files.createFile(index.toPath());
+            }
+            if (!Files.isRegularFile(index.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("stored.rules is not a regular file directly in the store folder");
+            }
+            state.folderCanonical = folder.getCanonicalFile().toPath();
+            state.indexCanonical = index.getCanonicalFile().toPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot create or access violation store at %s", index.getAbsolutePath()), e);
+        }
+    }
+
+    private static Properties loadProperties(File index) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(index)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private void rejectIfInconsistent(IntegrityInspection inspection) {
+        if (!inspection.hasProblems()) {
+            return;
+        }
+        StringBuilder report = new StringBuilder("Violation store integrity check failed:\n");
+        appendEntries(report, "broken", inspection.brokenEntries);
+        appendEntries(report, "resolved", inspection.resolvedEntries);
+        appendEntries(report, "shared", inspection.sharedEntries);
+        appendFiles(report, "unowned", inspection.unownedFiles);
+        appendEntries(report, "misplaced", inspection.misplacedEntries);
+        appendEntries(report, "colliding", inspection.collidingEntries);
+        appendEntries(report, "occupied", inspection.occupiedEntries);
+        throw new StoreInitializationFailedException(report.toString());
+    }
+
+    private void appendEntries(StringBuilder report, String condition, List<Entry> entries) {
+        if (entries.isEmpty()) {
+            return;
+        }
+        report.append(condition).append(" entries:\n");
+        List<Entry> sorted = new ArrayList<>(entries);
+        Collections.sort(sorted, Comparator.comparing(entry -> entry.description));
+        for (Entry entry : sorted) {
+            report.append("  ").append(entry.description).append(" -> ").append(entry.recordedName).append('\n');
+        }
+    }
+
+    private void appendFiles(StringBuilder report, String condition, List<String> files) {
+        if (files.isEmpty()) {
+            return;
+        }
+        report.append(condition).append(" files:\n");
+        List<String> sorted = new ArrayList<>(files);
+        Collections.sort(sorted);
+        for (String file : sorted) {
+            report.append("  ").append(file).append('\n');
+        }
+    }
+
+    private IntegrityInspection inspect(Properties properties, StoreState state) {
+        IntegrityInspection result = new IntegrityInspection();
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String normalizedDescription = ensureUnixLineBreaks(description);
+            String recordedName = ensureUnixLineBreaks(properties.getProperty(description));
+            String derivedName = deriveNameForInitialization(normalizedDescription);
+            Entry entry = new Entry(normalizedDescription, recordedName, derivedName, state);
+            entry.path = resolveEntryPath(recordedName, state);
+            if (!entry.path.valid) {
+                entry.broken = true;
+            } else {
+                try {
+                    entry.resolved = readLines(entry.path.resolved).isEmpty();
+                } catch (RuntimeException e) {
+                    entry.broken = true;
+                }
+            }
+            entry.misplaced = !recordedName.equals(derivedName);
+            entries.add(entry);
+        }
+
+        Map<String, List<Entry>> entriesByRecordedName = groupBy(entries, entry -> entry.recordedName);
+        Map<String, List<Entry>> entriesByResolvedFile = groupBy(entries,
+                entry -> entry.path.valid ? entry.path.identity : null);
+        Map<String, List<Entry>> entriesByDerivedName = groupBy(entries, entry -> entry.derivedName);
+        Set<String> recordedNames = new HashSet<>();
+        for (Entry entry : entries) {
+            recordedNames.add(entry.recordedName);
+            List<Entry> sameRecordedName = entriesByRecordedName.get(entry.recordedName);
+            List<Entry> sameFile = entry.path.valid ? entriesByResolvedFile.get(entry.path.identity) : null;
+            entry.shared = sameRecordedName.size() > 1 || sameFile != null && sameFile.size() > 1;
+            entry.colliding = entriesByDerivedName.get(entry.derivedName).size() > 1;
+            if (entry.misplaced) {
+                Path derivedPath = canonicalPathInOrOutsideFolder(entry.derivedName, state);
+                entry.occupied = !isDirectSafePath(derivedPath, state)
+                        || Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS)
+                        || recordedByAnotherEntry(entry, recordedNames, entries);
+                if (entry.path.isIndex) {
+                    entry.occupied = true;
+                }
+            }
+        }
+
+        for (Entry entry : entries) {
+            if (entry.broken) result.brokenEntries.add(entry);
+            if (entry.resolved) result.resolvedEntries.add(entry);
+            if (entry.shared) result.sharedEntries.add(entry);
+            if (entry.misplaced) result.misplacedEntries.add(entry);
+            if (entry.colliding) result.collidingEntries.add(entry);
+            if (entry.occupied) result.occupiedEntries.add(entry);
+        }
+
+        Set<String> ownedFiles = new HashSet<>();
+        for (Entry entry : entries) {
+            if (entry.path.valid) {
+                ownedFiles.add(entry.path.identity);
+            }
+        }
+        File[] children = state.folder.listFiles();
+        if (children != null) {
+            for (File child : children) {
+                if (STORED_RULES_FILE_NAME.equals(child.getName())) {
+                    continue;
+                }
+                Path childPath = child.toPath();
+                if (Files.isRegularFile(childPath, LinkOption.NOFOLLOW_LINKS)) {
+                    String identity = fileIdentity(childPath);
+                    if (!ownedFiles.contains(identity)) {
+                        result.unownedFiles.add(child.getName());
+                    }
+                }
+            }
+        }
+        return result;
+    }
+
+    private boolean recordedByAnotherEntry(Entry entry, Set<String> recordedNames, List<Entry> entries) {
+        if (!recordedNames.contains(entry.derivedName)) {
+            return false;
+        }
+        for (Entry other : entries) {
+            if (other != entry && entry.derivedName.equals(other.recordedName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private <T> Map<T, List<Entry>> groupBy(List<Entry> entries, KeyFunction<T> keyFunction) {
+        Map<T, List<Entry>> result = new HashMap<>();
+        for (Entry entry : entries) {
+            T key = keyFunction.key(entry);
+            if (key != null) {
+                result.computeIfAbsent(key, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+        return result;
+    }
+
+    private void repair(Properties properties, StoreState state, IntegrityInspection inspection) {
+        boolean changed = false;
+
+        for (Entry entry : inspection.entries()) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                properties.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteResolvedEntryFile(entry, state);
+                properties.remove(entry.description);
+                changed = true;
+            }
+        }
+
+        for (Entry entry : inspection.entries()) {
+            if (!entry.shared && !entry.broken && !entry.resolved && entry.misplaced
+                    && !entry.colliding && !entry.occupied) {
+                moveEntryFile(entry, state);
+                properties.setProperty(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+
+        if (changed) {
+            writePropertiesAtomically(properties, state);
+        }
+    }
+
+    private void deleteResolvedEntryFile(Entry entry, StoreState state) {
+        if (entry.path.isIndex) {
+            throw new StoreInitializationFailedException("Cannot repair an entry that records stored.rules");
+        }
+        try {
+            Path recordedPath = entry.path.lexical;
+            boolean link = Files.isSymbolicLink(recordedPath);
+            if (link) {
+                Files.delete(recordedPath);
+            }
+            Files.deleteIfExists(entry.path.resolved);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot delete resolved violation file for rule '%s'", entry.description), e);
+        }
+    }
+
+    private void moveEntryFile(Entry entry, StoreState state) {
+        if (entry.path.isIndex) {
+            throw new StoreInitializationFailedException("Cannot repair an entry that records stored.rules");
+        }
+        Path destination = canonicalPathInOrOutsideFolder(entry.derivedName, state);
+        if (!isDirectSafePath(destination, state) || Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot move violation file for rule '%s' to '%s'", entry.description, entry.derivedName));
+        }
+        try {
+            moveWithoutReplacing(entry.path.resolved, destination);
+            if (Files.isSymbolicLink(entry.path.lexical)) {
+                Files.delete(entry.path.lexical);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
+        }
+    }
+
+    private String deriveNameForInitialization(String description) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.trim().isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        StoreState state = requireInitialized();
+        synchronized (state.lock) {
+            return state.properties.containsKey(ensureUnixLineBreaks(rule.getDescription()));
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s=true)",
+                    ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        StoreState state = requireInitialized();
+        synchronized (state.lock) {
+            String description = ensureUnixLineBreaks(rule.getDescription());
+            String existingName = state.properties.getProperty(description);
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                if (existingName != null) {
+                    forgetKnownRule(description, existingName, state);
+                }
+                return;
+            }
+
+            String fileName = existingName == null ? deriveNameForSave(description) : existingName;
+            Path target = writableTarget(fileName, existingName != null, state, description);
+            byte[] contents = encodeViolations(violations);
+            boolean newRule = existingName == null;
+            writeFileAtomically(target, contents, state);
+            if (newRule) {
+                state.properties.setProperty(description, ensureUnixLineBreaks(fileName));
+                try {
+                    writePropertiesAtomically(state.properties, state);
+                } catch (RuntimeException e) {
+                    try {
+                        Files.deleteIfExists(target);
+                    } catch (IOException ignored) {
+                        // The original index is still intact; the next integrity pass will report the orphan.
+                    }
+                    state.properties.remove(description);
+                    throw e;
+                }
+            }
+        }
+    }
+
+    private String deriveNameForSave(String description) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.trim().isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private void forgetKnownRule(String description, String existingName, StoreState state) {
+        IntegrityInspection inspection = inspect(state.properties, state);
+        Entry known = null;
+        for (Entry entry : inspection.entries()) {
+            if (description.equals(entry.description)) {
+                known = entry;
+                break;
+            }
+        }
+        if (known == null) {
+            return;
+        }
+        if (!known.shared && known.path.valid) {
+            try {
+                if (known.path.isIndex) {
+                    throw new IOException("stored.rules cannot be deleted");
+                }
+                if (Files.isSymbolicLink(known.path.lexical)) {
+                    Files.delete(known.path.lexical);
+                }
+                Files.deleteIfExists(known.path.resolved);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Cannot delete violation file '%s' while forgetting rule '%s'", existingName, description));
+            }
+        } else if (!known.shared && Files.exists(known.path.lexical, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot delete violation file '%s' while forgetting rule '%s'", existingName, description));
+        }
+
+        state.properties.remove(description);
+        writePropertiesAtomically(state.properties, state);
+    }
+
+    private byte[] encodeViolations(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append('\n');
+        }
+        return builder.toString().getBytes(UTF_8);
